    new Person("Ewa", 30), new Person("Adam", 15), new Person("Beata", 22),
    new Person("Cezary", 17), new Person("Dawid", 40), new Person("Franek", 18)
);
List<String> adultsSortedByAge = people.stream()
        .filter(p -> p.getAge() >= 18)
        .sorted(Comparator.comparingInt(Person::getAge))
        .map(Person::getName)
        .toList();
