class Order {
    int id; List<String> items;
    Order(int id, List<String> items) { this.id = id; this.items = items; }
    List<String> getItems() { return items; }
}

List<Order> orders = List.of(
    new Order(1, List.of("chleb", "mleko")),
    new Order(2, List.of("mleko", "jajka", "maslo")),
    new Order(3, List.of("chleb", "woda"))
);
List<String> uniqueProducts = orders.stream()
        .flatMap(order -> order.getItems().stream())
        .distinct()
        .sorted()
        .toList();
System.out.println(uniqueProducts);

