class Product {
    String name, category; double price, rating;
    Product(String name, String category, double price, double rating) {
        this.name = name; this.category = category; this.price = price; this.rating = rating;
    }
    String getCategory() { return category; } double getRating() { return rating; }
    public String toString() { return name + " (" + rating + ")"; }
}

List<Product> products = List.of(
    new Product("Laptop", "Electronics", 3500, 4.5),
    new Product("Mysz", "Electronics", 100, 3.8),
    new Product("Monitor", "Electronics", 900, 4.7),
    new Product("Krzeslo", "Furniture", 400, 4.2),
    new Product("Sluchawki", "Electronics", 250, 4.9),
    new Product("Telefon", "Electronics", 2500, 4.1),
    new Product("Biurko", "Furniture", 600, 4.6),
    new Product("Klawiatura", "Electronics", 200, 3.9)
);

List<Product> top3 = products.stream()
        .filter(p -> p.getCategory().equals("Electronics") && p.getRating() >= 4.0)
        .sorted(Comparator.comparingDouble(Product::getRating).reversed())
        .limit(3)
        .toList();
System.out.println("TOP 3: " + top3);
